  /* HERO_SKILL_GROUPS_BEGIN */
  function groupHeroSkills(details) {
    const list = details.querySelector(':scope > ul');
    if (!list) return;
    const groups = {auto: [], active: [], passive: [], aura: []};
    for (const row of Array.from(list.children)) {
      const title = row.querySelector('b')?.textContent || '';
      const kind = row.matches('[data-integrated-passive]') ? 'passive'
        : row.classList.contains('au') ? (title.startsWith('Аура вашего героя:') ? 'aura' : 'passive')
        : row.querySelector('.scd')?.textContent === 'автоатака' ? 'auto' : 'active';
      groups[kind].push(row);
    }
    const labels = {auto: 'Автоматическое действие', active: 'Активные умения', passive: 'Пассивные эффекты', aura: 'Аура'};
    const sections = [];
    for (const kind of Object.keys(groups)) {
      if (!groups[kind].length) continue;
      const section = document.createElement('section'), title = document.createElement('h4'), ul = document.createElement('ul');
      section.dataset.skillGroup = kind; title.textContent = labels[kind];
      ul.append(...groups[kind]); section.append(title, ul); sections.push(section);
    }
    list.replaceWith(...sections);
    const aura = Array.from(details.children).find(n => n.tagName === 'P' && n.textContent.startsWith('Аура:'));
    if (aura) {
      const section = document.createElement('section'), title = document.createElement('h4');
      section.dataset.skillGroup = 'aura'; title.textContent = labels.aura;
      aura.before(section); section.append(title, aura);
    }
  }
  /* HERO_SKILL_GROUPS_END */
const hero=$('w-hero');
